<!doctype html><html><head><meta charset="utf-8"><title>Passbook</title><style>body{font-family:Arial;background:#0f2027;color:#fff;margin:0;padding:30px}.wrap{max-width:1100px;margin:auto}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#ffffff18;padding:18px;border-radius:16px;margin-bottom:16px}.label{color:#ffc107;font-size:12px;font-weight:bold}.value{font-size:28px;margin-top:8px}.filters{display:flex;gap:10px;flex-wrap:wrap}.filters>*{padding:10px;border-radius:10px}.btn{background:#ffc107;border:0;font-weight:bold}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #ffffff22;text-align:left}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:500px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><h1>Passbook</h1><div class="grid"><div class="card"><div class="label">Withdrawal Point</div><div class="value">{{$total_withdrawal_point}}</div></div><div class="card"><div class="label">Total Point</div><div class="value">{{$student_point}}</div></div><div class="card"><div class="label">Total Payment</div><div class="value">{{$total_amount}}</div></div><div class="card"><div class="label">Requested Withdrawal</div><div class="value">{{$total_request_withdrawal_point}}</div></div></div><div class="card"><form id="f" class="filters">@csrf<input type="date" name="filter_start_date" value="{{$filter_start_date}}"><input type="date" name="filter_end_date" value="{{$filter_end_date}}"><select name="filter_type"><option value="">All</option><option>Credit</option><option>Debit</option></select><button class="btn">Filter</button></form></div><div class="card"><table><thead><tr><th>ID</th><th>Reason</th><th>Credit</th><th>Debit</th><th>Balance</th><th>Added</th><th>Note</th></tr></thead><tbody id="rows"></tbody></table></div></div><script>async function load(){let p=new URLSearchParams(new FormData(f));p.set('length',1000);let r=await fetch('{{route('student.passbook.list')}}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('[name=_token]').value},body:p}),j=await r.json();rows.innerHTML=j.data.map(x=>'<tr><td>'+x.id+'</td><td>'+x.reason+'</td><td>'+x.credit_point+'</td><td>'+x.debit_point+'</td><td>'+x.balance_point+'</td><td>'+x.created_at+'</td><td>'+x.description+'</td></tr>').join('')}f.onsubmit=e=>{e.preventDefault();load()};load();</script></body></html>